def mark_duplicate_devices(apps, schema_editor):
    """Before the uniqueness constraints: a device entered twice keeps its number on the first record;
    the later copies get "~<id>" appended (nothing is deleted — they stay visible to fix by hand)."""
    SerialItem = apps.get_model('inventory', 'SerialItem')
    for field in ('imei_1', 'serial_number'):
        seen = set()
        for item in SerialItem.objects.exclude(**{f'{field}__isnull': True}).exclude(**{field: ''}).order_by('id'):
            value = getattr(item, field)
            if value in seen:
                limit = 100 if field == 'serial_number' else 20
                suffix = f'~{item.pk}'                       # the record id keeps it unique after cutting
                setattr(item, field, value[:limit - len(suffix)] + suffix)
                item.save(update_fields=[field])
            else:
                seen.add(value)


